// api/api.js - All the functions that talk to our backend
// We use axios library for making HTTP requests
// Keeping all API calls in one place makes the code organized

import axios from 'axios';

// The base URL of our backend
// In development, the backend runs on port 8000
// We use an environment variable so it's easy to change for production
const BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000';

// Create an axios instance with our base URL
// All requests will automatically use this base URL
const api = axios.create({
  baseURL: BASE_URL,
  timeout: 10000 // Give up after 10 seconds
});

// ============================================================
// SENSOR DATA API CALLS
// ============================================================

/**
 * Get paginated sensor readings
 * @param {number} page - Which page number (starts at 1)
 * @param {number} pageSize - How many results per page
 * @param {string} topic - Optional: filter by MQTT topic
 * @param {string} startTime - Optional: filter by start time
 * @param {string} endTime - Optional: filter by end time
 */
export async function getSensorReadings({
  page = 1,
  pageSize = 20,
  topic = null,
  startTime = null,
  endTime = null
} = {}) {
  // Build query parameters
  const params = {
    page,
    page_size: pageSize
  };
  if (topic) params.topic = topic;
  if (startTime) params.start_time = startTime;
  if (endTime) params.end_time = endTime;
  const response = await api.get('/api/sensor-data/', {
    params
  });
  return response.data;
}

/**
 * Get the latest reading from each sensor topic
 * Used on the dashboard overview
 */
export async function getLatestReadings() {
  const response = await api.get('/api/sensor-data/latest');
  return response.data;
}

/**
 * Get overall statistics (total readings, total topics)
 */
export async function getSensorStats() {
  const response = await api.get('/api/sensor-data/stats');
  return response.data;
}

/**
 * Get all unique MQTT topics we have data for
 */
export async function getAllTopics() {
  const response = await api.get('/api/sensor-data/topics');
  return response.data;
}

// ============================================================
// ALERTS API CALLS
// ============================================================

/**
 * Get paginated alerts list
 * @param {number} page - Page number
 * @param {number} pageSize - Results per page
 * @param {string} severity - Optional: 'WARNING' or 'CRITICAL'
 * @param {string} topic - Optional: filter by topic
 */
export async function getAlerts({
  page = 1,
  pageSize = 20,
  severity = null,
  topic = null
} = {}) {
  const params = {
    page,
    page_size: pageSize
  };
  if (severity) params.severity = severity;
  if (topic) params.topic = topic;
  const response = await api.get('/api/alerts/', {
    params
  });
  return response.data;
}

