 * @param {string} startTime - Optional: filter by start time
 * @param {string} endTime - Optional: filter by end time
 */
export async function getSensorReadings({ page = 1, pageSize = 20, topic = null, startTime = null, endTime = null } = {}) {
  // Build query parameters
  const params = { page, page_size: pageSize };
  if (topic) params.topic = topic;
  if (startTime) params.start_time = startTime;
  if (endTime) params.end_time = endTime;

  const response = await api.get('/api/sensor-data/', { params });
  return response.data;
}

/**
 * Get the latest reading from each sensor topic
 * Used on the dashboard overview
 */
export async function getLatestReadings() {
  const response = await api.get('/api/sensor-data/latest');
  return response.data;
}

/**
 * Get overall statistics (total readings, total topics)
