export async function getAlerts({ page = 1, pageSize = 20, severity = null, topic = null } = {}) {
  const params = { page, page_size: pageSize };
  if (severity) params.severity = severity;
  if (topic) params.topic = topic;

  const response = await api.get('/api/alerts/', { params });
  return response.data;
}

/**
 * Get the 5 most recent alerts for the dashboard
 */
export async function getRecentAlerts(limit = 5) {
  const response = await api.get('/api/alerts/recent', { params: { limit } });
  return response.data;
}

/**
 * Get alert statistics (total, critical, warning counts)
 */
export async function getAlertStats() {
  const response = await api.get('/api/alerts/stats');
  return response.data;
